// Synthetic tone + existing pattern.png, muxed independently with FFmpeg.
export const encodedCovers = {
  "cover.mp3":
    "",
  "cover.flac":
    "",
  "cover.m4a":
    "",
  "cover.opus":
    "",
  "cover.ogg":
    "",
} as const;
export function coverBytes(name: keyof typeof encodedCovers): Uint8Array<ArrayBuffer> {
  return Uint8Array.from(atob(encodedCovers[name]), (c) => c.charCodeAt(0));
}
